#!/usr/bin/env python3
"""drug/covalent_docking — auto-generated run.py (archetype=drug).

第一版只实现 simulate 模式:从 stdin/args 拿 inputs,产合理合成数据 JSON。
真实现路径(simulate=False)留 stub:返回 not-implemented + 提示。

输入契约:
  stdin JSON,字段按 SKILL.md 的 inputs 段;simulate 默认 true。
  CLI 兜底:--simulate / 各位置参数。

输出:
  stdout JSON;失败时也写 JSON {"ok": false, "error": "..."} 而非裸 traceback。
"""
import json
import sys

ARCHETYPE = "drug"
BRAIN = "drug"
SKILL = "covalent_docking"

def simulate(payload):
    """auto-generated by regen_simulate.py — outputs schema 来自 SKILL.md."""
    import copy
    import random
    random.seed(int(payload.get("seed", 42)) if isinstance(payload, dict) else 42)
    out = copy.deepcopy({'skill_id': 'covalent_docking', 'n_compounds': 0, 'best_score': 0.0, 'compound_csv': '', 'diagnostics': {'brain': 'drug', 'archetype': 'drug'}})
    if isinstance(out, dict):
        out.setdefault("diagnostics", {})
        if isinstance(out["diagnostics"], dict):
            out["diagnostics"].update({
                "simulated": True,
                "archetype": ARCHETYPE,
                "brain": BRAIN,
                "skill": SKILL,
            })
        if "skill_id" in out and not out["skill_id"]:
            out["skill_id"] = SKILL
    return out

def real(payload):
    """drug 版 covalent docking:简化(vina + warhead 后过滤)。"""
    return real_from_dock_pattern(payload)

def real_from_dock_pattern(payload):
    """vina dock + warhead-distance 后过滤(简化共价 docking,host 无 AD-FR)。"""
    import os as _os
    import tempfile as _tempfile
    import time as _time
    try:
        from brains._common.lib.run_tool import run_tool
    except ImportError:
        import sys as _sys
        _sys.path.insert(0, "/home/zkyd/data1/mzy/praxis2-brains")
        from _common.lib.run_tool import run_tool  # noqa: F401

    receptor = payload.get("receptor_pdb")
    ligand_sdf = payload.get("ligand_sdf") or payload.get("ligand")
    target_residue = payload.get("target_residue", "CYS:145:SG")
    distance_cutoff = float(payload.get("distance_cutoff_A", 2.5))
    out_dir = payload.get("out_dir") or _tempfile.mkdtemp(prefix="cov_dock_drug_")
    diagnostics = {"brain": BRAIN, "skill": SKILL, "archetype": ARCHETYPE,
                   "target_residue": target_residue, "method": "vina+post-filter",
                   "out_dir": out_dir}

    if _os.environ.get("PRAXIS_SKILL_DRY_HOST") == "1":
        return {"ok": True, "skill_id": SKILL, "receptor": receptor or "", "ligand": ligand_sdf or "",
                "best_affinity": 0.0,
                "poses": [{"rank": 1, "affinity_kcal_per_mol": 0.0, "pose_path": ""}],
                "n_covalent_compatible_poses": 0, "runtime_sec": 0.0,
                "diagnostics": {**diagnostics, "dry": True}}
    if not receptor or not _os.path.isfile(receptor):
        return {"ok": False, "error": f"receptor_pdb 不存在", "diagnostics": diagnostics}
    if not ligand_sdf or not _os.path.isfile(ligand_sdf):
        return {"ok": False, "error": f"ligand_sdf 不存在", "diagnostics": diagnostics}

    out_sdf = _os.path.join(out_dir, "docked.sdf")
    cmd = ["vina", "--receptor", receptor, "--ligand", ligand_sdf, "--autobox_ligand", ligand_sdf,
           "--exhaustiveness", "16", "--num_modes", "20", "--out", out_sdf]
    t0 = _time.time()
    r = run_tool(cmd, timeout=int(payload.get("timeout_s", 1200)))
    diagnostics["subprocess"] = {"wall_sec": r.get("wall_sec"), "rc": r.get("returncode")}
    if not r["ok"]:
        return {"ok": False, "error": r.get("error", "vina 失败"),
                "stderr": r.get("stderr", "")[-300:], "diagnostics": diagnostics}
    poses = []
    for ln in r["stdout"].splitlines():
        parts = ln.split()
        if len(parts) >= 4 and parts[0].isdigit():
            try:
                poses.append({"rank": int(parts[0]),
                              "affinity_kcal_per_mol": float(parts[1]),
                              "pose_path": out_sdf})
            except ValueError:
                continue
    return {"ok": True, "skill_id": SKILL,
            "receptor": receptor, "ligand": ligand_sdf,
            "best_affinity": poses[0]["affinity_kcal_per_mol"] if poses else 0.0,
            "poses": poses,
            "n_covalent_compatible_poses": -1,
            "runtime_sec": round(_time.time() - t0, 2),
            "diagnostics": {**diagnostics, "note": "warhead 距离后过滤需 Bio.PDB,本 stub 仅给 vina dock 结果"}}

